<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {Lock,Iphone,Message,ChatDotRound,User} from '@element-plus/icons-vue';
import {useAccount} from '@/store/modules/account.store';
import {request,post,patch,remove} from '@/utils/request';
import {date} from '@/utils/format';
const account=useAccount(),sessions=ref<any[]>([]),editing=ref(false),passwordDialog=ref(false),busy=ref(false);
const profile=reactive<any>({}),password=reactive({currentPassword:'',newPassword:'',confirm:''});
async function load(){await account.load();sessions.value=await request('/me/sessions');}
onMounted(load);
function editProfile(){Object.assign(profile,account.profile,{currentPassword:''});editing.value=true;}
async function saveProfile(){busy.value=true;try{await patch('/me/profile',profile);await account.load();editing.value=false;ElMessage.success('账户资料已更新');}finally{busy.value=false;}}
function editPassword(){Object.assign(password,{currentPassword:'',newPassword:'',confirm:''});passwordDialog.value=true;}
async function savePassword(){if(password.newPassword!==password.confirm){ElMessage.warning('两次输入的新密码不一致');return;}if(password.newPassword.length<12){ElMessage.warning('新密码至少 12 位');return;}busy.value=true;try{await post('/me/password',password);await window.api?.closeAll();await window.api?.setSession('');sessionStorage.removeItem('spb-token');ElMessage.success('密码已更新，请重新登录');location.hash='/login';}finally{busy.value=false;}}
async function revoke(session:any){try{await ElMessageBox.confirm('结束该登录会话？该会话之后的请求将无法访问账户。','剔除登录');}catch{return;}await remove(`/me/sessions/${session.id}`);sessions.value=await request('/me/sessions');ElMessage.success('该会话已退出');}
const client=(agent:string)=>agent.includes('Electron')?'桌面客户端':agent.includes('Edg/')?'Microsoft Edge':agent.includes('Chrome')?'Chrome 浏览器':agent||'历史登录';
</script>
<template><section class="panel security-page"><h1 class="page-title">账号安全设置</h1><div class="security-overview"><section class="security-basic"><h2 class="block-title"><el-icon><User/></el-icon>企业基本信息<el-button link type="primary" @click="editProfile">修改资料</el-button></h2><dl class="account-details"><dt>姓名</dt><dd>{{account.profile?.displayName}}</dd><dt>用户名</dt><dd>{{account.profile?.username}}</dd><dt>账号 ID</dt><dd class="break-word">{{account.profile?.id}}</dd><dt>角色</dt><dd>{{account.profile?.roles?.join('、')||'未分配角色'}}</dd><dt>企业名称</dt><dd>{{account.profile?.companyName}}</dd><dt>创建时间</dt><dd>{{date(account.profile?.createdAt)}}</dd></dl></section>
  <section class="security-login"><h2 class="block-title">登录方式 / 账号安全</h2><div class="security-row"><el-icon class="security-icon"><Lock/></el-icon><div><b>账号密码登录 <el-tag type="success" size="small">已设置</el-tag></b><p>通过用户名和密码登录，修改密码后所有会话将退出。</p></div><el-button type="primary" @click="editPassword">修改密码</el-button></div><div v-for="item in [{name:'绑定手机号',icon:Iphone,text:'可用于手机号验证与账号找回，短信服务尚未开通'},{name:'绑定微信公众号',icon:ChatDotRound,text:'可用于微信扫码登录，公众号登录服务尚未开通'},{name:'绑定邮箱',icon:Message,text:'可用于邮箱验证与账号找回，邮件验证服务尚未开通'}]" :key="item.name" class="security-row"><el-icon class="security-icon"><component :is="item.icon"/></el-icon><div><b>{{item.name}} <el-tag type="info" size="small">未绑定</el-tag></b><p>{{item.text}}</p></div><el-button disabled>暂未开通</el-button></div></section></div>
  <div class="section-toolbar"><h2 class="block-title">我的登录会话</h2><el-button @click="load">刷新</el-button></div><el-table :data="sessions"><el-table-column label="登录成员" min-width="140"><template #default>{{account.profile?.username}}</template></el-table-column><el-table-column label="终端平台" min-width="140"><template #default="{row}">{{client(row.clientName)}}</template></el-table-column><el-table-column prop="remoteAddress" label="登录 IP"/><el-table-column label="登录状态"><template #default="{row}"><el-tag :type="row.currentSession?'success':'info'">{{row.currentSession?'当前会话':'有效会话'}}</el-tag></template></el-table-column><el-table-column label="登录时间" min-width="175"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column><el-table-column label="到期时间" min-width="175"><template #default="{row}">{{date(row.expiresAt)}}</template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button link type="danger" :disabled="Boolean(row.currentSession)" @click="revoke(row)">剔除登录</el-button></template></el-table-column></el-table>
  <el-dialog v-model="editing" title="修改账户资料" width="540px"><el-form label-width="105px"><el-form-item label="姓名"><el-input v-model="profile.displayName" maxlength="120"/></el-form-item><el-form-item label="用户名"><el-input v-model="profile.username" maxlength="80"/></el-form-item><el-form-item v-if="profile.username!==account.profile?.username" label="当前密码"><el-input v-model="profile.currentPassword" type="password" show-password placeholder="修改用户名需验证当前密码"/></el-form-item><el-form-item label="企业名称"><el-input v-model="profile.companyName" :disabled="!account.profile?.owner" maxlength="120"/></el-form-item></el-form><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveProfile">保存</el-button></template></el-dialog>
  <el-dialog v-model="passwordDialog" title="修改登录密码" width="540px" :close-on-click-modal="false"><el-form label-width="100px"><el-form-item label="当前密码"><el-input v-model="password.currentPassword" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="新密码"><el-input v-model="password.newPassword" type="password" show-password placeholder="至少 12 位，UTF-8 不超过 72 字节" autocomplete="new-password"/></el-form-item><el-form-item label="确认新密码"><el-input v-model="password.confirm" type="password" show-password autocomplete="new-password"/></el-form-item></el-form><template #footer><el-button @click="passwordDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="savePassword">确认修改</el-button></template></el-dialog>
</section></template>
